<script setup>
import {computed} from 'vue'
import {useCreation} from '@/ports/creation'
import Icon from '../components/CreationIcon.vue'
import ProductScene from '../components/ProductScene.vue'
import MediaCover from '../components/MediaCover.vue'
const p=useCreation(),s=p.state
const filtered=computed(()=>s.assets.filter(a=>(s.assetType==='全部'||a.type===s.assetType)&&(s.category==='全部'||a.category===s.category)&&(!s.search||a.name.includes(s.search)||a.tags.some(t=>t.includes(s.search)))))
</script>
<template><div class="assets-page"><header class="home-top"><span>我的工作空间 <span class="separator">/</span> 个人资产</span><span class="subtle-chip"><Icon name="folder" :size="13"/>仅自己可见</span></header><div class="assets-heading"><div><span class="eyebrow">YOUR CREATIVE LIBRARY</span><h1>个人资产<span>{{s.assets.length}}</span></h1><p>把好灵感留下，让下一次创作更轻松。</p></div><button class="primary-button" @click="p.openModal('save',{type:'提示词',text:'',name:''})"><Icon name="plus"/>保存提示词</button></div><div class="asset-filters"><div class="filter-tabs"><button v-for="t in ['全部','图片','视频','音频','提示词']" :key="t" :class="{active:s.assetType===t}" @click="s.assetType=t">{{t}}</button></div><label class="search-box"><Icon name="search" :size="16"/><input v-model="s.search" aria-label="搜索资产" placeholder="搜索名称或标签"/></label></div><div class="category-bar"><span>保存位置</span><button v-for="t in ['全部','角色','场景','物品','风格','音效']" :key="t" :class="{active:s.category===t}" @click="s.category=t">{{t}}</button></div><div v-if="s.loading" class="assets-grid"><div v-for="n in 4" :key="n" class="skeleton asset-skeleton"></div></div><div v-else-if="s.failed" class="empty-panel"><h3>资产加载失败</h3><button class="secondary-button" @click="p.retry()">重试</button></div><div v-else-if="!filtered.length" class="empty-panel"><Icon name="search" :size="28"/><h3>还没有匹配的资产</h3><p>调整筛选，或从画布中右键保存喜欢的结果。</p></div><div v-else class="assets-grid"><article v-for="a in filtered" :key="a.id" class="asset-card"><button class="asset-preview" @click="p.openModal('asset-detail',a)"><div v-if="a.type==='提示词'" class="prompt-preview"><Icon name="text" :size="24"/><p>{{a.text}}</p><span>提示词 / PROMPT</span></div><MediaCover v-else :asset="a"/><span class="asset-type">{{a.type}}</span></button><div class="asset-info"><h3>{{a.name}}</h3><div class="asset-tags"><span v-for="t in a.tags" :key="t">{{t}}</span><button title="引用到画布" @click="p.openModal('apply',a)"><Icon name="link" :size="16"/></button></div></div></article></div><div class="asset-note"><Icon name="save" :size="15"/>只有手动保存的内容会进入个人资产，生成记录仍保留在项目中。</div></div></template>
